function normalizeHeader(value:string){return value.toLowerCase().replace(/^\ufeff/,"").replace(/[^a-z0-9]/g,"")}
const contactEmailPattern=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const genericMailboxNames=new Set(["admin","accounts","benefits","billing","careers","contact","customerservice","donotreply","hello","help","hr","info","inquiries","jobs","listserv","mail","marketing","newsletter","noreply","oa","office","ogoa","postmaster","sales","service","stds","support","team","webmaster"]);
